package dev.thefoolish.generated.anishelf;
import android.content.*;import android.util.Base64;import android.widget.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class DetailActivity extends AppScreen{protected void render(){String id=n(getIntent().getStringExtra("id")),t=n(getIntent().getStringExtra("title")),summary=n(getIntent().getStringExtra("summary")),provider=n(getIntent().getStringExtra("provider"));int eps=getIntent().getIntExtra("episodes",0);title(t.length()==0?"Anime":t);subtitle(summary.length()==0?"No description supplied by provider.":summary);Set<String> favs=store.set("favorites");String prefix=enc(provider)+"|"+enc(id)+"|";boolean saved=contains(favs,prefix);Button fav=button(saved?"Remove from Library":"Add to Library");fav.setOnClickListener(v->{Set<String>s=store.set("favorites");remove(s,prefix);if(!savedNow(s,prefix))s.add(prefix+enc(t)+"|"+enc(summary)+"|"+eps);store.set("favorites",s);recreate();});body.addView(fav);MediaProvider p=findProvider(provider);boolean playable=p!=null&&p.supportsPlayback();subtitle(playable?"This provider declares episode playback.":"This source is catalog metadata only; choose a playable provider to watch episodes.");body.addView(text("Episodes",18,true));if(eps<=0)subtitle("This provider did not supply an episode count.");for(int x=1;x<=Math.min(eps,100);x++){final int ep=x;Button b=button("Episode "+x+(store.number("progress_"+id+"_"+x)>0?" · Resume":""));b.setEnabled(playable);b.setOnClickListener(v->{Intent i=new Intent(this,PlayerActivity.class);i.putExtra("id",id);i.putExtra("title",t);i.putExtra("provider",provider);i.putExtra("episode",ep);startActivity(i);});body.addView(b);}nav();}private MediaProvider findProvider(String id){MediaProvider p=BuiltInProviderCatalog.find(id);if(p!=null)return p;ExtensionRecord x=new ExtensionManager(this).find(id);return x==null?null:new RepositoryMediaProvider(x);}private boolean contains(Set<String>s,String p){for(String x:s)if(x.startsWith(p))return true;return false;}private boolean savedNow(Set<String>s,String p){return contains(s,p);}private void remove(Set<String>s,String p){String hit=null;for(String x:s)if(x.startsWith(p)){hit=x;break;}if(hit!=null)s.remove(hit);}private String n(String s){return s==null?"":s;}private String enc(String s){return Base64.encodeToString(n(s).getBytes(StandardCharsets.UTF_8),Base64.NO_WRAP|Base64.URL_SAFE);}}
